// Knowledge Base Retrieval Simulator (Simulates Vector Store Retrieval in n8n)
const query = ($input.first().json.body?.query || 'What is the launch date for Project NovaStar?').toLowerCase();

// Enterprise Knowledge Base (mirroring takeaway/sample_docs.json)
const knowledgeBase = [
  {
    id: 'doc-1',
    title: 'Project NovaStar Technical Specifications & Launch Plan',
    content: 'Project NovaStar is QuantumNovas flagship orbital communications satellite system. Launch date: November 24, 2026 aboard the Falcon Heavy. Frequency band: Ka-band (26.5-40 GHz). Orbit: Geostationary at 35,786 km. Total budget: $420 million USD. Lead contractor: Orbital Dynamics Corp.'
  },
  {
    id: 'doc-2',
    title: 'QuantumNova Internal Office Policies & Perks',
    content: 'Headquarters located in Seattle, WA. The high-speed internal office Wi-Fi network SSID is QuantumNova-Corp-5G and password is StellarNebula2026! All full-time employees receive a $1,500 annual wellness stipend. Core working hours are 10:00 AM to 4:00 PM Pacific Time.'
  },
  {
    id: 'doc-3',
    title: 'Customer Refund and Return Policy (Revised 2026)',
    content: 'Standard software licenses are eligible for 100% full refund within 45 days of purchase. Hardware returns incur a 15% restocking fee. Subscriptions cancelled mid-cycle will receive prorated store credit calculated to the exact day.'
  },
  {
    id: 'doc-4',
    title: 'Executive Leadership Directory & Biographies',
    content: 'CEO: Dr. Arthur Pendelton (MIT graduate, severe peanut allergy, favorite dessert: cannoli). CTO: Elena Rostova (former lead architect at CERN). CFO: Marcus Vance (ex-Goldman Sachs partner). General Counsel: Sarah Jenkins.'
  }
];

// Keyword / Semantic similarity matching
const tokens = query.replace(/[^a-z0-9]/g, ' ').split(/\s+/).filter(w => w.length > 2);

const scoredDocs = knowledgeBase.map(doc => {
  const docText = (doc.title + ' ' + doc.content).toLowerCase();
  let score = 0;
  tokens.forEach(t => {
    if (docText.includes(t)) score += 1;
  });
  return { ...doc, score };
});

scoredDocs.sort((a, b) => b.score - a.score);
const topDocs = scoredDocs.filter(d => d.score > 0).slice(0, 2);

return [{
  json: {
    query: $input.first().json.body?.query || 'What is the launch date for Project NovaStar?',
    retrievedCount: topDocs.length,
    retrievedDocs: topDocs.length > 0 ? topDocs : [knowledgeBase[0]]
  }
}];

const item = $input.first().json;
const docs = item.retrievedDocs;

let contextStr = docs.map((d, idx) => `[Document ${idx + 1}]: ${d.title}\nExcerpt: ${d.content}`).join('\n\n');

const prompt = `You are QuantumNova's enterprise knowledge assistant.\n` +
  `CRITICAL INSTRUCTIONS:\n` +
  `1. Answer the user question EXCLUSIVELY based on the verified context below.\n` +
  `2. Always cite the document title or number used.\n` +
  `3. If the context does not contain the answer, say 'I do not have this information in my verified knowledge base.'\n\n` +
  `--- RETRIEVED CONTEXT ---\n${contextStr}\n--- END CONTEXT ---\n\n` +
  `User Question: ${item.query}\n\nAnswer:`;

return [{
  json: {
    query: item.query,
    retrievedDocs: docs,
    augmentedPrompt: prompt
  }
}];

const geminiResp = $input.first().json;
const ragData = $('Prompt Augmentation').first().json;

let answer = 'No response generated';
if (geminiResp.candidates && geminiResp.candidates.length > 0) {
  answer = geminiResp.candidates[0].content?.parts[0]?.text || '';
}

return [{
  json: {
    success: true,
    query: ragData.query,
    answer: answer.trim(),
    retrievedDocuments: ragData.retrievedDocs.map(d => ({ title: d.title, excerpt: d.content })),
    pipeline: ['User Query', 'Vector Search Retrieval', 'Augmented Prompt Grounding', 'Gemini Flash Generation'],
    model: 'gemini-flash-latest'
  }
}];
